function goTo(path) {
  if (typeof window !== "undefined") window.location.href = path;
}

/* ============================================================
   Animated counter
   ============================================================ */
function useCounter(target, duration = 1600, start = false) {
  const [count, setCount] = useState(0);
  useEffect(() => {
    if (!start) return;
    let startTime = null;
    const step = (ts) => {
      if (!startTime) startTime = ts;
      const progress = Math.min((ts - startTime) / duration, 1);
      const ease = 1 - Math.pow(1 - progress, 4);
      setCount(Math.floor(ease * target));
      if (progress < 1) requestAnimationFrame(step);
      else setCount(target);
    };
    requestAnimationFrame(step);
  }, [target, duration, start]);
  return count;
}

function Stat({ value, suffix = "", label, started }) {
  const displayed = useCounter(value, 1600, started);
  return (
    <div style={{ padding: "22px 0 0", borderTop: `1px solid ${C.hairline}` }}>
      <div style={{ fontFamily: display, fontWeight: 600, fontSize: "2.4rem", color: C.text, lineHeight: 1 }}>
        {displayed}{suffix}
      </div>
      <div style={{ fontFamily: body, fontSize: "0.8rem", color: C.muted, marginTop: 8 }}>
        {label}
      </div>
    </div>
  );
}

/* ============================================================
   Scroll-reveal hook — one shared pattern used across sections,
   fires once when the element enters the viewport.
   ============================================================ */
function useReveal(threshold = 0.15) {
  const ref = useRef(null);
  const [shown, setShown] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    if (typeof window !== "undefined" && window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setShown(true);
      return;
    }
    const obs = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) { setShown(true); obs.disconnect(); }
    }, { threshold });
    obs.observe(node);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, shown];
}

